import codecs,json,sys,unicodedata
rows=[]
for name in ['gb2312','hz','gbk','big5','iso2022_jp','iso2022_kr']:
 for direction,invalid in [('encode',[-1,1<<136,9]),('decode',[-1,1<<64])]:
  for state in invalid:
   obj=(codecs.getincrementalencoder(name) if direction=='encode' else codecs.getincrementaldecoder(name))()
   if direction=='encode': obj.encode('A',False)
   else: obj.decode(b'A',False)
   before=obj.getstate()
   try:
    obj.setstate(state if direction=='encode' else (b'',state))
    result=['ok']
   except Exception as error: result=[type(error).__name__,str(error)]
   def pack(value):
    return str(value) if isinstance(value,int) else [list(value[0]),str(value[1])]
   rows.append(dict(name=name,direction=direction,invalid=str(state),before=pack(before),result=result,after=pack(obj.getstate())))
print(json.dumps(dict(version=sys.version,unicode=unicodedata.unidata_version,platform=sys.platform,byteorder=sys.byteorder,rows=rows)))

